source /root/.env && python3 << 'PYEOF'
import json, sys

with open('/tmp/email-workflow-full.json') as f:
    w = json.load(f)

# Build the update payload
nodes = w['nodes']

for node in nodes:
    # 1. Modify Extract Email Content to filter blank emails
    if node['name'] == 'Extract Email Content':
        node['parameters']['jsCode'] = """const items = $input.all();
const results = [];

for (const item of items) {
  const subject = item.json.subject || '(no subject)';
  const from = item.json.from || 'unknown';
  const date = item.json.date || new Date().toISOString();
  let body = item.json.textPlain || item.json.text || '';
  if (!body && (item.json.html || item.json.textHtml)) {
    body = (item.json.html || item.json.textHtml).replace(/<[^>]*>/g, ' ').replace(/\\s+/g, ' ').trim();
  }
  if (body.length > 3000) body = body.substring(0, 3000) + '\\n[...truncated]';

  // Skip blank/empty emails (no real subject AND no body)
  const hasSubject = subject && subject !== '(no subject)';
  const hasBody = body && body.trim().length > 10;
  if (!hasSubject && !hasBody) {
    continue; // Skip this email
  }

  const raw_content = 'Subject: ' + subject + '\\nFrom: ' + from + '\\nDate: ' + date + '\\n\\n' + body;
  results.push({ json: { subject, from, date, body, raw_content } });
}
return results;"""

    # 2. Add retry on fail to AI Classify Email
    if node['name'] == 'AI Classify Email':
        node['retryOnFail'] = True
        node['maxTries'] = 3
        node['waitBetweenTries'] = 5000

# Build PUT payload (only include fields n8n accepts)
payload = {
    "name": w['name'],
    "nodes": nodes,
    "connections": w['connections'],
    "settings": w['settings'],
    "staticData": w['staticData']
}

with open('/tmp/email-workflow-update.json', 'w') as f:
    json.dump(payload, f)

print("Payload written, size:", len(json.dumps(payload)))
PYEOF
